/** Waits until `check` holds or half a second passes, so teardown never hangs on a socket that will not die. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Registers a server a suite built itself, so the teardown below stops it. */
export function trackServer(hal: HalServer): void {
  servers.push(hal);
}

/** Registers a socket a suite built itself, so the teardown below closes it. */
export function trackClient(client: WebSocket): void {
  clients.push(client);
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    // Each server sees its sockets close before it stops, so no close is logged after a suite has restored the logger.
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

/** A store with only the five required members, so an optional one can be added, replaced or left out per test. */
export const delegatingStore = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

// The frames a list_sessions validator must refuse, so the validator's unit test and the protocol suite try the same ones.
export const MALFORMED_LIST_SESSIONS: Array<Record<string, unknown>> = [
  {type: 'list_sessions', limit: 'ten'},
  {type: 'list_sessions', limit: -1},
  {type: 'list_sessions', limit: 1.5},
  {type: 'list_sessions', before: 'not-an-object'},
